<?php namespace App\Features\Auth\Livewire;use Livewire\Component;use App\Features\Auth\Actions\RegisterUserAction;
class Register extends Component{public string $name='';public string $username='';public string $email='';public string $password='';public string $password_confirmation='';public function register(RegisterUserAction $action){$data=$this->validate(['name'=>'required|string|max:100','username'=>'required|string|max:30|unique:users','email'=>'required|email|unique:users','password'=>'required|min:8|confirmed']);$user=$action->execute($data);auth()->login($user);request()->session()->regenerate();return redirect('/stocks');}public function render(){return view('livewire.auth.register')->layout('components.layouts.app');}}
